type Props = {
  subview: string;
  horizon: string;
  profile: string;
  scenarioStep: number;
  stage: Stage;
  mapStatus: string;
  layers: Record<string, boolean>;
  selectedAsset: string;
  renderMap: () => ReactNode;
  onHorizon: (value: string) => void;
  onToggleLayer: (key: string) => void;
  onSelectAsset: (value: string) => void;
  onAgents: () => void;
  onToast: (message: string) => void;
  onTwin: () => void;
  onHazards: () => void;
  onTower: () => void;
  onPlanning: () => void;
  onRisk: () => void;
};

