  return <div className="chain-view"><section className="chain-rail-grid"><article className="panel chain-rail-map"><Head eyebrow="RAIL FLOW INTELLIGENCE" title="EFVM · origem ao recebimento" side={<Pill tone="watch">4 TRENS EM FILA</Pill>} /><div className="chain-map-embed">{props.renderMap()}<div className="rail-route"><i /><i /><i /><i /><i /><span className="train t1">T-482</span><span className="train t2">T-477</span><span className="terminal">TUBARÃO</span></div><div className="chain-map-status"><i />Rede operacional própria · não usa rota pública</div></div></article><aside className="panel chain-rail-summary"><Head eyebrow="QUEUE STATE" title="Recebimento ferroviário" /><div className="chain-big-stat"><strong>4</strong><span>trens em espera<small>média 2h18</small></span></div>{[["Agora", 3], ["+6H", 4], ["+12H", 6], ["+24H", 2]].map(([time, value]) => <div className="queue-step" key={time as string}><span>{time}</span><i><b style={{ width: `${Number(value) * 14}%` }} /></i><strong>{value}</strong></div>)}<button onClick={() => props.onToast("Discrete Event Simulation executada para taxa de serviço do virador")}>Recalcular fila</button></aside></section><article className="panel chain-train-table"><Head eyebrow="TRAIN MOVEMENTS" title="ETA, volume, descarga e efeito no buffer" side={<button onClick={() => props.onToast("RailSignal publicado no Event Bus")}>Publicar atualização</button>} /><table><thead><tr><th>Trem</th><th>Origem</th><th>Carga</th><th>ETA plano</th><th>ETA atual</th><th>Desvio</th><th>Fila</th><th>Impacto imediato</th></tr></thead><tbody>{[["T-482", "Itabira", "14,2 kt", "21:10", eta === 54 ? "22:04" : "21:32", `+${eta} min`, "3º", "Nenhum · buffer 8h42"], ["T-477", "Brucutu", "13,8 kt", "20:42", "20:51", "+9 min", "1º", "Nenhum"], ["T-486", "Timbopeba", "14,0 kt", "22:20", "22:46", "+26 min", "4º", "Atenção +12h"], ["T-490", "Fábrica", "14,1 kt", "23:05", "23:08", "+3 min", "5º", "Nenhum"]].map((row) => <tr key={row[0]}>{row.map((cell, index) => <td key={cell}>{index === 0 ? <strong>{cell}</strong> : index === 5 ? <Pill tone={cell === "+54 min" ? "alert" : "watch"}>{cell}</Pill> : cell}</td>)}</tr>)}</tbody></table></article><section className="chain-rail-controls"><article className="panel"><Head eyebrow="WHAT-IF ETA" title="T-482 · atraso controlado" /><label>Desvio de ETA<input type="range" min="0" max="120" step="6" value={eta} onChange={(event) => setEta(Number(event.target.value))} /><strong>+{eta} min</strong></label><p>{eta <= 60 ? "O Pátio Minério absorve o atraso; nenhuma perda imediata na U3." : "Autonomia cai abaixo de 7h; fila e entrada prevista passam a afetar o forecast."}</p></article><article className="panel"><Head eyebrow="RAIL AGENT" title="Diagnóstico" side={<Pill tone={eta <= 60 ? "ok" : "watch"}>{eta <= 60 ? "BUFFERED" : "MATERIAL"}</Pill>} /><dl><div><dt>Volume postergado</dt><dd>{Math.ceil(eta / 30) * 14} kt</dd></div><div><dt>Fila projetada +12h</dt><dd>{eta > 60 ? 7 : 6} trens</dd></div><div><dt>Autonomia minério</dt><dd>{eta > 60 ? "6h58" : "8h42"}</dd></div><div><dt>Confidence ETA</dt><dd>68%</dd></div></dl></article></section></div>;
